// Package domain contains primitives shared by IAM domain services.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
)

// ID is the opaque identifier used by domain entities.
type ID string

type (
	UserID         ID
	OrganizationID ID
	SessionID      ID
	RoleID         ID
	InviteID       ID
	APIKeyID       ID
)

// NewID returns a cryptographically random 128-bit identifier.
func NewID() (ID, error) {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", fmt.Errorf("generate domain id: %w", err)
	}
	return ID(hex.EncodeToString(raw[:])), nil
}

// MustNewID is intended for initialization paths where random generation
// failure cannot be recovered from.
func MustNewID() ID {
	id, err := NewID()
	if err != nil {
		panic(err)
	}
	return id
}

func NewUserID() (UserID, error) {
	id, err := NewID()
	return UserID(id), err
}

func NewOrganizationID() (OrganizationID, error) {
	id, err := NewID()
	return OrganizationID(id), err
}

func NewSessionID() (SessionID, error) {
	id, err := NewID()
	return SessionID(id), err
}

func NewRoleID() (RoleID, error) {
	id, err := NewID()
	return RoleID(id), err
}

func NewInviteID() (InviteID, error) {
	id, err := NewID()
	return InviteID(id), err
}

func NewAPIKeyID() (APIKeyID, error) {
	id, err := NewID()
	return APIKeyID(id), err
}
package domain

import "time"

// Clock abstracts time for domain logic and makes time-dependent behavior
// deterministic in callers that provide their own implementation.
type Clock interface {
	Now() time.Time
}

type SystemClock struct{}

func (SystemClock) Now() time.Time { return time.Now().UTC() }
package domain

import "errors"

var (
	ErrNotFound     = errors.New("not found")
	ErrConflict     = errors.New("conflict")
	ErrInvalid      = errors.New("invalid")
	ErrUnauthorized = errors.New("unauthorized")
)

// Error is a typed domain error with a stable category and a safe message.
type Error struct {
	Kind    error
	Message string
}

func (e *Error) Error() string {
	if e.Message == "" {
		return e.Kind.Error()
	}
	return e.Message
}

func (e *Error) Unwrap() error { return e.Kind }

func NotFound(message string) error {
	return &Error{Kind: ErrNotFound, Message: message}
}

func Conflict(message string) error {
	return &Error{Kind: ErrConflict, Message: message}
}

func Invalid(message string) error {
	return &Error{Kind: ErrInvalid, Message: message}
}

func Unauthorized(message string) error {
	return &Error{Kind: ErrUnauthorized, Message: message}
}
// Package app owns the top-level dependency wiring for the IAM process.
package app

import (
	"net/http"

	"benchmark.local/iam/internal/config"
	"benchmark.local/iam/internal/domain"
)

type App struct {
	Config config.Config
	Clock  domain.Clock
}

func New(cfg config.Config) (*App, error) {
	return NewWithClock(cfg, domain.SystemClock{})
}

func NewWithClock(cfg config.Config, clock domain.Clock) (*App, error) {
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	if clock == nil {
		return nil, domain.Invalid("clock must not be nil")
	}
	return &App{Config: cfg, Clock: clock}, nil
}

func (a *App) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	return mux
}
